import{_ as a,o,c as i,ae as t}from"./chunks/framework.dxkK2hvP.js";const u=JSON.parse('{"title":"【大数据系列】Hadoop 分布式大数据集群部署","description":"使用三台 AlmaLinux 虚拟机演示 Hadoop 分布式大数据集群的基础环境准备、Hadoop、ZooKeeper 与 Hive 的部署流程。","frontmatter":{"top":-2,"title":"【大数据系列】Hadoop 分布式大数据集群部署","description":"使用三台 AlmaLinux 虚拟机演示 Hadoop 分布式大数据集群的基础环境准备、Hadoop、ZooKeeper 与 Hive 的部署流程。","sticky":6,"categories":["Linux 分布式集群"],"outline":[2,3],"date":"2024-10-15T00:00:00.000Z","recommend":0,"tags":["运维","分布式","Linux","Hadoop"],"head":[["meta",{"name":"keywords","content":"Linux企业级运维, 分布式, Linux, 架构, Hadoop, 大数据, ZooKeeper, Hive"}]],"cover":"https://cdn.imufeng.cn/mblog/202411161415899.jpg"},"headers":[],"relativePath":"training/linux/hadoop-cluster/index.md","filePath":"training/linux/hadoop-cluster/index.md","lastUpdated":1774319582000}'),l={name:"training/linux/hadoop-cluster/index.md"};function d(r,e,n,p,s,c){return o(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1728950400000"},[...e[0]||(e[0]=[t('<h1 id="hadoop-分布式大数据集群部署" tabindex="-1">Hadoop 分布式大数据集群部署 <a class="header-anchor" href="#hadoop-分布式大数据集群部署" aria-label="Permalink to &quot;Hadoop 分布式大数据集群部署&quot;">​</a></h1><p>本系列使用三台 <code>Vmware Workstation</code> 环境下的 <code>AlmaLinux</code> 虚拟机作为演示环境，按“环境准备 → Hadoop → ZooKeeper → Hive”的顺序，逐步搭建一套可用于学习和实验的 Hadoop 分布式集群。</p><h2 id="系列说明" tabindex="-1">系列说明 <a class="header-anchor" href="#系列说明" aria-label="Permalink to &quot;系列说明&quot;">​</a></h2><ul><li>演示环境以教学和实验为主，采用单独的 <code>Master</code> 节点与两台 <code>Node</code> 节点。</li><li>文中配置偏向快速搭建，便于理解 Hadoop 生态中各组件之间的依赖关系。</li><li>生产环境应进一步补充独立账户、权限隔离、监控告警、高可用与备份策略。</li></ul><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="./overview.html">第一章 Hadoop 分布式大数据系统概述</a></li><li><a href="./preparations.html">第二章 分布式环境准备</a></li><li><a href="./hadoop-install.html">第三章 Hadoop 集群部署</a></li><li><a href="./zookeeper-install.html">第四章 ZooKeeper 集群部署</a></li><li><a href="./hive-install.html">第五章 Hive 数据仓库部署</a></li></ul><h2 id="建议阅读顺序" tabindex="-1">建议阅读顺序 <a class="header-anchor" href="#建议阅读顺序" aria-label="Permalink to &quot;建议阅读顺序&quot;">​</a></h2><p>首次搭建建议严格按照目录顺序操作，尤其是以下前置步骤不可跳过：</p><ol><li>完成三台节点的网络、主机名与 <code>hosts</code> 配置。</li><li>完成 SSH 免密登录与 JDK 安装。</li><li>先部署 Hadoop，再部署 ZooKeeper，最后部署 Hive。</li></ol>',9)])])}const m=a(l,[["render",d]]);export{u as __pageData,m as default};
